const staticData = $getWorkflowStaticData("global");
const bookings = staticData.bookings || [];
const booked = bookings.map(b => b.slot_id);
return [{ json: { booked } }];

const raw = $input.first().json;
const body = raw.body || raw;

// Required fields
const required = ["slot_id","date","time","name","email","phone","agency"];
for (const field of required) {
  if (!body[field] || String(body[field]).trim() === "") {
    return [{ json: { error: "missing_field", field, status: 400 } }];
  }
}

// Slot ID format YYYY-MM-DD_HH:MM
if (!/^\d{4}-\d{2}-\d{2}_\d{2}:\d{2}$/.test(body.slot_id)) {
  return [{ json: { error: "invalid_slot_id", status: 400 } }];
}

const [datePart, timePart] = body.slot_id.split("_");
const [yr, mo, dy] = datePart.split("-").map(Number);
const [hr, mn] = timePart.split(":").map(Number);

// Mon-Fri only
const dow = new Date(yr, mo - 1, dy).getDay();
if (dow === 0 || dow === 6) {
  return [{ json: { error: "weekend_slot", status: 400 } }];
}

// Time range 09:00-16:30
const slotMins = hr * 60 + mn;
if (slotMins < 540 || slotMins > 990) {
  return [{ json: { error: "invalid_time", status: 400 } }];
}

// 1-hour minimum notice (AWST = UTC+8, subtract 8h to get UTC)
const slotUTC = Date.UTC(yr, mo - 1, dy, hr - 8, mn);
if (slotUTC - Date.now() < 60 * 60 * 1000) {
  return [{ json: { error: "insufficient_notice", status: 400 } }];
}

// 60-day window
const nowAWST = Date.now() + 8 * 3600000;
const maxDate = new Date(nowAWST);
maxDate.setUTCDate(maxDate.getUTCDate() + 60);
if (new Date(Date.UTC(yr, mo - 1, dy)) > maxDate) {
  return [{ json: { error: "outside_window", status: 400 } }];
}

// Email format
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) {
  return [{ json: { error: "invalid_email", status: 400 } }];
}

// Conflict check using staticData
const staticData = $getWorkflowStaticData("global");
const bookings = staticData.bookings || [];
if (bookings.some(b => b.slot_id === body.slot_id)) {
  return [{ json: { error: "slot_taken", status: 409 } }];
}

// Book it
const booking = {
  slot_id: body.slot_id,
  date: body.date,
  time: body.time,
  name: body.name.trim(),
  email: body.email.trim().toLowerCase(),
  phone: body.phone.trim(),
  agency: body.agency.trim(),
  message: (body.message || "").trim(),
  booked_at: new Date().toISOString()
};
staticData.bookings = [...bookings, booking];
return [{ json: { success: true, booking } }];

